(1892385, 260447, 45857, '<td valign="top">Excellant compostion and masterfull tonal control. Only weakness is the fact that your subject is in the ''darker'' side of your picture. The picture seems to go from light to dark, from right to left, as shown in the lostt of detail in the red drawing.<br/>I think there might be enough range for a general lightening to work in bringing out more detail, or a gradient adjustment or selective dodge/burn outside the challenge.<br/>I really like this a lot, keep up the good work.</td>', 'Excellant compostion and masterfull tonal control. Only weakness is the fact that your subject is in the ''darker'' side of your picture. The picture seems to go from light to dark, from right to left, as shown in the lostt of detail in the red drawing.I think there might be enough range for a general lightening to work in bringing out more detail, or a gradient adjustment or selective dodge/burn outside the challenge.I really like this a lot, keep up the good work.', '2005-11-23 12:16:02.000000', NULL, 1),
(1892389, 259328, 32644, '<td valign="top">Great concept. Beautiful in its own way. Definately out of the box and fits the challenge very well.</td>', 'Great concept. Beautiful in its own way. Definately out of the box and fits the challenge very well.', '2005-11-23 12:17:22.000000', NULL, 1),
(1892390, 260892, 32644, '<td valign="top">Even though I am sick of dice shots, this is my favorite so far.</td>', 'Even though I am sick of dice shots, this is my favorite so far.', '2005-11-23 12:18:09.000000', NULL, 1),
(1892395, 259995, 32644, '<td valign="top">WOW! Beautiful! Very nice capture.</td>', 'WOW! Beautiful! Very nice capture.', '2005-11-23 12:19:13.000000', NULL, 1),
(1892399, 259129, 32644, '<td valign="top">Beautiful hands and funny concept.</td>', 'Beautiful hands and funny concept.', '2005-11-23 12:20:23.000000', NULL, 1),
