(1894701, 260381, 45414, '<td valign="top">too sharp</td>', 'too sharp', '2005-11-24 02:37:50.000000', NULL, 1),
(1894702, 260821, 39675, '<td valign="top">This is Mr. Czaja.  I think this definately qualifies for odd.  I like the randomness of the photo.  I think this is the perfect challenge to attempt something like this.  Good use of color, light, and props to make this shot interesting.  I don''t know if you tried to use Unsharp Mask or not, but if not, it looks like it could have used it a bit.  Good job!</td>', 'This is Mr. Czaja.  I think this definately qualifies for odd.  I like the randomness of the photo.  I think this is the perfect challenge to attempt something like this.  Good use of color, light, and props to make this shot interesting.  I don''t know if you tried to use Unsharp Mask or not, but if not, it looks like it could have used it a bit.  Good job!', '2005-11-24 02:37:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1894704, 260214, 44882, '<td valign="top">A really good shot, not fitting the theme enough.</td>', 'A really good shot, not fitting the theme enough.', '2005-11-24 02:39:34.000000', NULL, 1),
(1894706, 259139, 45414, '<td valign="top">it looks out of focus</td>', 'it looks out of focus', '2005-11-24 02:39:49.000000', NULL, 1),
(1894707, 259366, 45414, '<td valign="top">good idea</td>', 'good idea', '2005-11-24 02:40:22.000000', NULL, 1),
(1894708, 259596, 39675, '<td valign="top">Good idea and very well executed.  I just don''t like how there is so much black space the makes the frames appear that they are floating in a weightlessness.  There doesn''t seem to be a need for a reference frame of reference (no pun intended).  But, it is creative so I''ll bump you up for that.</td>', 'Good idea and very well executed.  I just don''t like how there is so much black space the makes the frames appear that they are floating in a weightlessness.  There doesn''t seem to be a need for a reference frame of reference (no pun intended).  But, it is creative so I''ll bump you up for that.', '2005-11-24 02:41:05.000000', NULL, 1),
(1894712, 260637, 39675, '<td valign="top">Not enough motion blur to make it look intentional, but you''re right this is odd.  Why wouldn''t one of the kids be wearing a helmet, and is that boy drinking through a straw?</td>', 'Not enough motion blur to make it look intentional, but you''re right this is odd.  Why wouldn''t one of the kids be wearing a helmet, and is that boy drinking through a straw?', '2005-11-24 02:43:30.000000', NULL, 1),
(1894715, 260802, 39675, '<td valign="top">Congratulations sarn!  this is by far your best photo.  It''s actually in focus too!  Good job. 8</td>', 'Congratulations sarn!  this is by far your best photo.  It''s actually in focus too!  Good job. 8', '2005-11-24 02:45:28.000000', NULL, 1),
(1894717, 261118, 39675, '<td valign="top">Very cool abstract work.  I''m not sure how you did this, but I like the result.</td>', 'Very cool abstract work.  I''m not sure how you did this, but I like the result.', '2005-11-24 02:46:22.000000', NULL, 1),
