(1894720, 260149, 45414, '<td valign="top">i like this</td>', 'i like this', '2005-11-24 02:51:55.000000', NULL, 1),
(1894721, 260277, 39675, '<td valign="top">That thing is amazing.  Image the girl who receives this corsage on prom night.</td>', 'That thing is amazing.  Image the girl who receives this corsage on prom night.', '2005-11-24 02:52:03.000000', NULL, 1),
(1894722, 258336, 45414, '<td valign="top">lovely picture</td>', 'lovely picture', '2005-11-24 02:52:53.000000', NULL, 1),
(1894723, 260851, 39675, '<td valign="top">Wow!  Awsome face.  I get a little tension with the fact that he''s so close to the right hand edge.  Maybe rule of thirds would have been good here.  But I have to reward such a wonderful face. 8.</td>', 'Wow!  Awsome face.  I get a little tension with the fact that he''s so close to the right hand edge.  Maybe rule of thirds would have been good here.  But I have to reward such a wonderful face. 8.', '2005-11-24 02:54:19.000000', NULL, 1),
(1894724, 260013, 47508, '<td valign="top">This is awesome...should be a 10!</td>', 'This is awesome...should be a 10!', '2005-11-24 02:54:36.000000', NULL, 1),
(1894725, 261009, 39675, '<td valign="top">Sorry to say, but this just doesn''t seem like a photo that should be entered into a photo competition.  Maybe for sharing with family and friends it''s great... but it is odd enough to fit the challenge description.</td>', 'Sorry to say, but this just doesn''t seem like a photo that should be entered into a photo competition.  Maybe for sharing with family and friends it''s great... but it is odd enough to fit the challenge description.', '2005-11-24 02:57:32.000000', NULL, 1),
(1894726, 260013, 39675, '<td valign="top">Love the glassy Neat Image feel to this photo.  Coloring is great.  I can''t help but giv ethis a 10.</td>', 'Love the glassy Neat Image feel to this photo.  Coloring is great.  I can''t help but giv ethis a 10.', '2005-11-24 02:58:44.000000', NULL, 1),
(1894727, 260214, 39675, '<td valign="top">I''ve got good news and bad news.  I would give this a 10 if I were simply voting on the qualty of the shot.  However, I just don''t feel the coloring is odd enough to justify this image getting a ribbon.  In fact, without the title I wouldn''t have realized anything was odd about the photo.  Therefore I have to mark it down to a 6.</td>', 'I''ve got good news and bad news.  I would give this a 10 if I were simply voting on the qualty of the shot.  However, I just don''t feel the coloring is odd enough to justify this image getting a ribbon.  In fact, without the title I wouldn''t have realized anything was odd about the photo.  Therefore I have to mark it down to a 6.', '2005-11-24 03:02:57.000000', NULL, 1),
(1894729, 259749, 45414, '<td valign="top">good profile of the good looking young boy</td>', 'good profile of the good looking young boy', '2005-11-24 03:04:21.000000', NULL, 1),
(1894730, 261156, 39675, '<td valign="top">I really don''t like all of the dice photos, or the playing cards, or gambling chips.  I really think they''re over done at DPC.  However, this maybe the best of the bunch.</td>', 'I really don''t like all of the dice photos, or the playing cards, or gambling chips.  I really think they''re over done at DPC.  However, this maybe the best of the bunch.', '2005-11-24 03:05:57.000000', NULL, 1),
