(1894732, 260615, 39675, '<td valign="top">Absolutely Gorgeous... Congratulations 10.</td>', 'Absolutely Gorgeous... Congratulations 10.', '2005-11-24 03:06:37.000000', NULL, 1),
(1894741, 261120, 37858, '<td valign="top">No animals were injured during the creation of this photo...I hope.</td>', 'No animals were injured during the creation of this photo...I hope.', '2005-11-24 03:28:34.000000', NULL, 1),
(1894744, 260970, 43589, '<td valign="top">LONGER I LOOKED THE MORE I LIKED IT. 8.</td>', 'LONGER I LOOKED THE MORE I LIKED IT. 8.', '2005-11-24 03:36:39.000000', NULL, 1),
(1894748, 259336, 43589, '<td valign="top">3 FEET 1YARD.</td>', '3 FEET 1YARD.', '2005-11-24 03:49:28.000000', NULL, 1),
(1894764, 259797, 45857, '<td valign="top">First off its a good nature shot (5) and its one thing (1). <br/>In biological terms, fungii are usually saphrophytic, feeding on dead organic matter. Since the symbiosis implies a relationship which benefits both organisms, I don''t think it applies in this instance. Thus endth the lesson.  5+1 = 6. plus one for reading this and smiling = 7<br/>(bump to 8, by compromise)</td>', 'First off its a good nature shot (5) and its one thing (1). In biological terms, fungii are usually saphrophytic, feeding on dead organic matter. Since the symbiosis implies a relationship which benefits both organisms, I don''t think it applies in this instance. Thus endth the lesson.  5+1 = 6. plus one for reading this and smiling = 7(bump to 8, by compromise)', '2005-11-24 04:28:33.000000', NULL, 1),
(1894768, 259763, 45857, '<td valign="top">European markets only, US adapter available at extra cost.<br/>Good lighting job.</td>', 'European markets only, US adapter available at extra cost.Good lighting job.', '2005-11-24 04:32:45.000000', NULL, 1),
