(1894801, 260630, 45857, '<td valign="top">Way too close!!!<br/>It would have been better if you had picked out that grren thing first....  :)</td>', 'Way too close!!!It would have been better if you had picked out that grren thing first....  :)', '2005-11-24 05:41:13.000000', NULL, 1),
(1894804, 259855, 45857, '<td valign="top">Got me smiling, I just hope there''s not an even number of ways.</td>', 'Got me smiling, I just hope there''s not an even number of ways.', '2005-11-24 05:42:43.000000', NULL, 1),
