(1898108, 260755, 44860, '<td valign="top">It would not be hard to remove mist in Photoshop (Autolevels/Autocontrast). If your idea was to leave the mist visible, you should come closer to the boy - he would become sharp and the background would be misty.</td>', 'It would not be hard to remove mist in Photoshop (Autolevels/Autocontrast). If your idea was to leave the mist visible, you should come closer to the boy - he would become sharp and the background would be misty.', '2005-11-26 09:49:06.000000', NULL, 1),
(1898110, 260590, 44860, '<td valign="top">Real expression of face. Sometimes life does not look nice, but it is beautiful anyway...</td>', 'Real expression of face. Sometimes life does not look nice, but it is beautiful anyway...', '2005-11-26 09:50:50.000000', NULL, 1),
(1898113, 261112, 44860, '<td valign="top">Nice composition. I would prefer more light.</td>', 'Nice composition. I would prefer more light.', '2005-11-26 09:52:00.000000', NULL, 1),
