(1903173, 260589, 46020, '<td valign="top">However beautiful this shot is, I just don''t see what is odd about it.</td>', 'However beautiful this shot is, I just don''t see what is odd about it.', '2005-11-28 19:47:08.000000', NULL, 1),
(1903198, 260381, 45961, '<td valign="top">I gave this a 4 because I''m not sure how it''s odd. The top view angle is great, but towards the side of the shot it starts becoming rather blurry. I''d probably give a 5 if it was better focused and still.<br/>Thank you very much for the explanation, so I just bumped this up to a 6 instead of 7 just because of the focus. It is odd indeed. I guess I just forgot about the odd numbers and was looking for strange. Looks like graffiti in the thumbnail.</td>', 'I gave this a 4 because I''m not sure how it''s odd. The top view angle is great, but towards the side of the shot it starts becoming rather blurry. I''d probably give a 5 if it was better focused and still.Thank you very much for the explanation, so I just bumped this up to a 6 instead of 7 just because of the focus. It is odd indeed. I guess I just forgot about the odd numbers and was looking for strange. Looks like graffiti in the thumbnail.', '2005-11-28 20:07:27.000000', NULL, 1),
(1903319, 260681, 41411, '<td valign="top">the composition is so even though..... I''m not a big fan of interpreting this challenge numerically.</td>', 'the composition is so even though..... I''m not a big fan of interpreting this challenge numerically.', '2005-11-28 21:05:49.000000', NULL, 1),
(1903322, 259763, 41411, '<td valign="top">Creative, yet I am dreadfully sick of isolated subject shots. The color is unflattering without being odd. four</td>', 'Creative, yet I am dreadfully sick of isolated subject shots. The color is unflattering without being odd. four', '2005-11-28 21:06:33.000000', NULL, 1),
(1903324, 260893, 41411, '<td valign="top">I don''t like the numerical interpretation of this challenge.</td>', 'I don''t like the numerical interpretation of this challenge.', '2005-11-28 21:07:15.000000', NULL, 1),
