(1904234, 260996, 30881, '<td valign="top">Not my personal favorite player but a great phot neverless. Really glad you chose b&amp;w for this shot</td>', 'Not my personal favorite player but a great phot neverless. Really glad you chose b&w for this shot', '2005-11-29 09:06:05.000000', NULL, 1),
(1904235, 260264, 30881, '<td valign="top">Nice imaginative shot. Very basic and yet so effective. No unnecessary clutter. Good job.</td>', 'Nice imaginative shot. Very basic and yet so effective. No unnecessary clutter. Good job.', '2005-11-29 09:08:06.000000', NULL, 1),
(1904247, 259840, 30881, '<td valign="top">Good lighting nice sharp feel to it. Well layed out, your lighting however pick up flaws in background that is a bit eye distracting. Otherwise almost perfect. Well Done!</td>', 'Good lighting nice sharp feel to it. Well layed out, your lighting however pick up flaws in background that is a bit eye distracting. Otherwise almost perfect. Well Done!', '2005-11-29 09:16:46.000000', NULL, 1),
(1904250, 260630, 30881, '<td valign="top">Way too much light and very unappealing subject matter unless of cours you''re a zoo vet.<br/>Don''t get discourage, a little more practise with lighting and you''ll have us all cheering.</td>', 'Way too much light and very unappealing subject matter unless of cours you''re a zoo vet.Don''t get discourage, a little more practise with lighting and you''ll have us all cheering.', '2005-11-29 09:19:14.000000', NULL, 1),
(1904253, 259712, 30881, '<td valign="top">Like the background, nice blur on the branches. The main subject could have been much sharper I think. Otherwise a good photo</td>', 'Like the background, nice blur on the branches. The main subject could have been much sharper I think. Otherwise a good photo', '2005-11-29 09:21:00.000000', NULL, 1),
(1904264, 260346, 30881, '<td valign="top">Nice lighting, background works well with main subject. Might have worked better with less leaf at the bottom. Overall very nicely done.</td>', 'Nice lighting, background works well with main subject. Might have worked better with less leaf at the bottom. Overall very nicely done.', '2005-11-29 09:28:32.000000', NULL, 1),
(1904270, 261132, 30881, '<td valign="top">Wonderful photography, clean, crisp, good lighting. The layout causes some eye distraction -lacking smooth eye flow. Otherwise very nice "9"</td>', 'Wonderful photography, clean, crisp, good lighting. The layout causes some eye distraction -lacking smooth eye flow. Otherwise very nice "9"', '2005-11-29 09:34:57.000000', NULL, 1),
(1904275, 260456, 30881, '<td valign="top">Very nicely done. Good subject matter , good layout, and nice lighting. Well thought out.<br/>Good job.</td>', 'Very nicely done. Good subject matter , good layout, and nice lighting. Well thought out.Good job.', '2005-11-29 09:38:13.000000', NULL, 1),
